"""Generate fixtures."""

import os
import json
import numpy as np
from scipy.special import erfc, expit

# Get the file path:
FILE = os.path.realpath(__file__)

# Extract the directory in which this file resides:
DIR = os.path.dirname(FILE)

# Constant sqrt(2/pi):
SQRT_TWO_DIVIDED_BY_PI = np.sqrt(2.0 / np.pi)


def eval_gelu(x):
    """Evaluate exact GELU formula."""
    return 0.5 * x * erfc(-x / np.sqrt(2.0))


def eval_tanh(x):
    """Evaluate GELU tanh approximation formula."""
    z = SQRT_TWO_DIVIDED_BY_PI * (x + 0.044715 * (x**3))
    return x * expit(2.0 * z)


def eval_quick(x):
    """Evaluate GELU quick approximation formula."""
    return x * expit(1.702 * x)


def gen(x, eval_fn, name):
    """Generate fixture data and writes them to file.

    # Arguments

    * `x`: domain
    * `eval_fn`: function to evaluate
    * `name::str`: output filename
    """
    x_arr = np.array(x, dtype=np.float64)
    y_arr = eval_fn(x_arr)
    data = {
        "x": x_arr.tolist(),
        "expected": y_arr.tolist()
    }
    filepath = os.path.join(DIR, name)
    with open(filepath, "w", encoding="utf-8", newline="\n") as outfile:
        json.dump(data, outfile)
        outfile.write("\n")


def main():
    """Generate fixture data."""
    # Exact GELU:
    x = [round(float(v), 4) for v in np.linspace(-1.0, 1.0, 101)]
    gen(x, eval_gelu, "gelu_near_zero.json")

    x = [round(float(v), 4) for v in np.linspace(-5.0, 5.0, 201)]
    gen(x, eval_gelu, "gelu_medium.json")

    x = [round(float(v), 2) for v in np.linspace(5.0, 50.0, 91)]
    gen(x, eval_gelu, "gelu_large_positive.json")

    x = [round(float(v), 2) for v in np.linspace(-35.0, -5.0, 121)]
    gen(x, eval_gelu, "gelu_large_negative.json")

    x = [round(float(v), 4) for v in np.linspace(-37.60, -38.60, 81)]
    gen(x, eval_gelu, "gelu_subnormal.json")

    x = [-40.0, -39.0, -38.6, -2.0, -1.0, 0.0, 1.0, 2.0, 10.0, 50.0]
    gen(x, eval_gelu, "gelu_special.json")

    # Tanh approximation:
    x = [round(float(v), 4) for v in np.linspace(-1.0, 1.0, 101)]
    gen(x, eval_tanh, "tanh_near_zero.json")

    x = [round(float(v), 4) for v in np.linspace(-5.0, 5.0, 201)]
    gen(x, eval_tanh, "tanh_medium.json")

    x = [round(float(v), 2) for v in np.linspace(5.0, 50.0, 91)]
    gen(x, eval_tanh, "tanh_large_positive.json")

    x = [round(float(v), 2) for v in np.linspace(-20.0, -5.0, 121)]
    gen(x, eval_tanh, "tanh_large_negative.json")

    x = [-50.0, -25.0, -22.0, -2.0, -1.0, 0.0, 1.0, 2.0, 10.0, 50.0]
    gen(x, eval_tanh, "tanh_special.json")

    # Quick approximation:
    x = [round(float(v), 4) for v in np.linspace(-1.0, 1.0, 101)]
    gen(x, eval_quick, "quick_near_zero.json")

    x = [round(float(v), 4) for v in np.linspace(-5.0, 5.0, 201)]
    gen(x, eval_quick, "quick_medium.json")

    x = [round(float(v), 2) for v in np.linspace(5.0, 50.0, 91)]
    gen(x, eval_quick, "quick_large_positive.json")

    x = [round(float(v), 2) for v in np.linspace(-400.0, -5.0, 159)]
    gen(x, eval_quick, "quick_large_negative.json")

    x = [-500.0, -450.0, -442.0, -2.0, -1.0, 0.0, 1.0, 2.0, 10.0, 50.0]
    gen(x, eval_quick, "quick_special.json")


if __name__ == "__main__":
    main()
